import { OverlaysEventEmitter } from '@game-studio/overlays';

import { SettingsEventEmitter } from '@game-studio/settings';
import { Bootstrap } from '../bootstrap';
import { gameConfig } from './config-model';
import { inversifyContainer } from '../inversify/container';
import { Injects } from '../inversify/injects';
import { queryStringParams } from '../services/query-string';
import { getLocaleString } from '../services/utilities';
import { IBaseServerResponse, IGameApp } from '../types';
import { userModel } from './user';

export interface IDemoModel {
    demoGamesRemaining: number;
    isDemoMode: boolean;
    isAuthenticatedDemo: boolean;
    isUnauthenticatedDemo: boolean;
}

export class DemoModel implements IDemoModel {
    public static get Instance(): DemoModel { return this._instance || (this._instance = new DemoModel()); }
    private static _instance: DemoModel;

    public isAuthenticatedDemo: boolean;
    public isUnauthenticatedDemo: boolean;
    public demoGamesRemaining: number;

    // Returns True if Authenticated or Unauthenticated Demo is Active
    public get isDemoMode(): boolean { return this.isAuthenticatedDemo || this.isUnauthenticatedDemo; }

    private constructor() {
        this.isAuthenticatedDemo = false;
        this.isUnauthenticatedDemo = false;
        this.demoGamesRemaining = 0;
    }

    public toggleDemoMode(): void {
        if (this.isDemoMode) {
            this.leaveDemoMode();
        } else {
            this.enterAuthenticatedDemo();
        }
    }

    public notifyChatDemoMode(): void {
        // Called after chat is initialized to notify it of demo mode
        // Used for unauthenticated demo where the flag is set in bootstrap
        if (!queryStringParams.isSubGame) {
            inversifyContainer.frameConnection.chat.setDemoMode({ show: true });
            OverlaysEventEmitter.emit('enterDemoMode');
        }
    }

    public async enterAuthenticatedDemo(): Promise<void> {
        if (inversifyContainer.gameModel.isInProgress) { return; }

        inversifyContainer.cabinet.disablePurchaseButton();
        inversifyContainer.cabinet.disableStakeButtons();

        this.isAuthenticatedDemo = true;
        
        if (!queryStringParams.isSubGame) {
            inversifyContainer.frameConnection.chat.setDemoMode({ show: true });
        }

        let gameComplete = true;
        try {
            const response = await inversifyContainer.gameServer.resumeRequest(gameConfig.engineSkinName);
            Bootstrap.handleResumeData(response);
            gameComplete = response.GameMessage && response.GameMessage.GameComplete;
        } catch (error) {
            this.isAuthenticatedDemo = false;
            if ((error as IBaseServerResponse).ResultCode?.ResultCode !== 2) {
                throw error; // throw unexpected errors
            }
            console.error('Error entering authenticated demo mode:', error);
        }
        inversifyContainer.cabinet.enterDemoMode();
        SettingsEventEmitter.emit('hide');

        inversifyContainer.frameConnection.operator.onSessionInfo({
            userId: userModel.userId,
            balance: userModel.totalBalance.startBalance,
            gameName: queryStringParams.currentSkin,
            version: gameConfig.version,
            sessionTime: 0, // TODO: leaving this as 0 for now as unused, may need adding later
            locale: getLocaleString()
        });

        if (gameComplete === false) {
            
            window.setTimeout(() => {
                const gameApp = inversifyContainer.get<IGameApp>(Injects.GameApp);
                gameApp.enterBonusRound();
            }, 2000);
        } else {
            inversifyContainer.cabinet.enablePurchaseButton();
            inversifyContainer.cabinet.updateStakeButtons();
        }

        OverlaysEventEmitter.emit('enterDemoMode');
    }

    public async leaveDemoMode(): Promise<void> {
        if (inversifyContainer.gameModel.isInProgress) { return; }
        
        const wasUnauthenticated = this.isUnauthenticatedDemo;

        this.isAuthenticatedDemo = false;
        this.isUnauthenticatedDemo = false;
        
        const event = demoState.demoGamesRemaining <= 0 ? 'outOfPlays' : 'leaveDemoMode';
        OverlaysEventEmitter.emit(event);

        if (!queryStringParams.isSubGame) {
            inversifyContainer.frameConnection.chat.setDemoMode({ show: false });
        }

        // Skip resume request if it was unauthenticated demo
        if (!wasUnauthenticated) {
            const response = await inversifyContainer.gameServer.resumeRequest(gameConfig.engineSkinName);
            Bootstrap.handleResumeData(response);
        }
        
        inversifyContainer.cabinet.leaveDemoMode();
        SettingsEventEmitter.emit('hide');
    }
}

export const demoState = DemoModel.Instance;
